SINA_SMART["anat2-pancreas"] = {"lecture":"anat2-pancreas","title":"The pancreas","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"anat2-pancreas:e0","text":"Pancreas: 12-20 cm, retroperitoneal, in front of L1-L2.","topic":"The big picture","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"anat2-pancreas:e1","text":"Exocrine (acini) + endocrine (islets: insulin, glucagon).","topic":"The big picture","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"anat2-pancreas:e3","text":"Head in the duodenal C; CBD in a posterior groove; on IVC.","topic":"Parts and relations","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"anat2-pancreas:e4","text":"Uncinate process behind SMA/SMV.","topic":"Parts and relations","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"anat2-pancreas:e6","text":"Body over aorta and L2; tail in splenorenal ligament to splenic hilum.","topic":"Parts and relations","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"anat2-pancreas:e7","text":"Wirsung + CBD → ampulla of Vater → major papilla; Santorini → minor papilla.","topic":"Duct system and variants","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"anat2-pancreas:e8","text":"Variants: annular pancreas, pancreas divisum.","topic":"Duct system and variants","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"anat2-pancreas:e10","text":"Veins: head → SMV/portal; body/tail → splenic vein.","topic":"Vessels, lymph and nerves","sec":3,"importance":"core","highYield":"insufficient-source"},{"id":"anat2-pancreas:e2","text":"Parts: head, uncinate process, neck, body, tail.","topic":"Vessels, lymph and nerves","sec":3,"importance":"core","highYield":"insufficient-source"},{"id":"anat2-pancreas:e5","text":"Neck over the portal vein (SMV + splenic vein).","topic":"Vessels, lymph and nerves","sec":3,"importance":"core","highYield":"insufficient-source"},{"id":"anat2-pancreas:e9","text":"Head: superior (GDA) + inferior (SMA) pancreaticoduodenal arcades; body/tail: splenic artery.","topic":"Vessels, lymph and nerves","sec":3,"importance":"core","highYield":"insufficient-source"}],"vmap":{},"mlevel":{"1wlch4f":"a","6cjtpk":"a","3yvftx":"a","1wdeux5":"a","1f1a749":"a","1dgp1fw":"a","w73zs8":"a","74274b":"a","1ib9ymw":"a","fsi8iz":"a","1c3dj8k":"a","132wjyj":"a","10ir5cj":"a"},"mapCounts":{"verified":0,"auto":13,"ambiguous":0,"missing":0},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"anat2-pancreas:e0":{"s":0,"u":["Pancreas: 12-20 cm, retroperitoneal, in front of L1-L2.","A soft, leaf-shaped, elongated gland 12-20 cm long with a thin capsule, retroperitoneal , lying behind the lesser sac, in front of L1-L2 , between the duodenum (right) and the spleen (left)."],"dp":[]},"anat2-pancreas:e1":{"s":0,"u":["Exocrine (acini) + endocrine (islets: insulin, glucagon).","It is both exocrine (acinar cells → pancreatic juice) and endocrine (islets → insulin and glucagon)."],"dp":[]},"anat2-pancreas:e3":{"s":1,"u":["Head in the duodenal C; CBD in a posterior groove; on IVC.","Head : in the C-curve of the duodenum, right of the superior mesenteric vessels, on the IVC and left renal vein; the bile duct runs in a groove on its posterosuperior surface."],"dp":[{"h":"Why pancreatic head cancer causes painless jaundice","t":"The common bile duct runs in a groove on the back of the pancreatic head and then through it to the ampulla. A tumour growing in the head squeezes the duct long before it causes much pain, so bile backs up: the patient turns yellow, with dark urine and pale stools, and a palpable, distended gallbladder may be felt. Tumours of the body and tail lack this early warning and are usually found later. Source: the lecture's head relations and duct slides."}]},"anat2-pancreas:e4":{"s":1,"u":["Uncinate process behind SMA/SMV.","Uncinate process : projects medially behind the SMA and SMV .","Neck : short, lies over the portal vein , formed behind it by the union of the SMV and splenic vein ."],"dp":[]},"anat2-pancreas:e6":{"s":1,"u":["Body over aorta and L2; tail in splenorenal ligament to splenic hilum.","Tail : mobile, runs in the splenorenal ligament with the splenic vessels to the splenic hilum , near the left colic flexure.","Body : left of the superior mesenteric vessels, crosses the aorta and L2 just above the transpyloric plane; its front, covered by peritoneum, forms the floor of the lesser sac and the stomach bed; behind are the aorta, left adrenal, left kidney and renal vessels."],"dp":[]},"anat2-pancreas:e7":{"s":2,"u":["Wirsung + CBD → ampulla of Vater → major papilla; Santorini → minor papilla.","The main pancreatic duct (of Wirsung) runs from tail to head and joins the common bile duct at the hepatopancreatic ampulla (of Vater) , opening at the major duodenal papilla in D2.","The accessory duct (of Santorini) drains the head and uncinate process and opens at the minor papilla ."],"dp":[{"h":"Note","t":"Ducts: main (Wirsung) + CBD → ampulla of Vater → major papilla ; accessory (Santorini) → minor papilla ."}]},"anat2-pancreas:e8":{"s":2,"u":["Variants: annular pancreas, pancreas divisum.","Variants: annular pancreas (ventral bud rotation failure, ring around D2) and pancreas divisum (no communication; the dorsal duct drains most of the gland via the minor papilla)."],"dp":[{"h":"Note","t":"Annular pancreas (ventral bud ring around D2) → duodenal obstruction; pancreas divisum (buds' ducts don't fuse) → most juice drains through the minor papilla: the commonest variant."}]},"anat2-pancreas:e10":{"s":3,"u":["Veins: head → SMV/portal; body/tail → splenic vein.","Veins: head → SMV and portal vein ; body and tail → splenic vein .","Body and tail: branches of the splenic artery (dorsal pancreatic, greater pancreatic, artery to the tail)."],"dp":[{"h":"Clinical","t":"Head tumour compresses the CBD → painless obstructive jaundice ; body/tail tumour → back pain, late presentation. Pancreatic pain radiates to the back ."}]},"anat2-pancreas:e2":{"s":3,"u":["Parts: head, uncinate process, neck, body, tail.","Veins: head → SMV and portal vein ; body and tail → splenic vein .","Head, neck and uncinate process: anterior and posterior superior pancreaticoduodenal arteries (from the gastroduodenal , coeliac territory) anastomosing with the inferior pancreaticoduodenal arteries (from the SMA ) in arcades; these arcades can supply the liver when the coeliac trunk is compressed ( median arcuate ligament syndrome )."],"dp":[{"h":"Note","t":"Retroperitoneal, L1-L2 . Parts: head (in the duodenal C), uncinate process (behind SMA/SMV), neck (in front of the portal vein), body (over aorta, L2), tail (in the splenorenal ligament, reaching the splenic hilum; the only intraperitoneal part)."}]},"anat2-pancreas:e5":{"s":3,"u":["Neck over the portal vein (SMV + splenic vein).","Veins: head → SMV and portal vein ; body and tail → splenic vein ."],"dp":[{"h":"Note","t":"Portal vein forms behind the neck from the SMV + splenic vein ."},{"h":"Clinical","t":"Splenic vein runs behind the pancreas: pancreatitis or tumour → splenic vein thrombosis → isolated gastric varices."}]},"anat2-pancreas:e9":{"s":3,"u":["Head: superior (GDA) + inferior (SMA) pancreaticoduodenal arcades; body/tail: splenic artery.","Head, neck and uncinate process: anterior and posterior superior pancreaticoduodenal arteries (from the gastroduodenal , coeliac territory) anastomosing with the inferior pancreaticoduodenal arteries (from the SMA ) in arcades; these arcades can supply the liver when the coeliac trunk is compressed ( median arcuate ligament syndrome ).","Body and tail: branches of the splenic artery (dorsal pancreatic, greater pancreatic, artery to the tail)."],"dp":[{"h":"Note","t":"Double supply : head from superior (GDA, coeliac) and inferior (SMA) pancreaticoduodenal arcades; body and tail from the splenic artery . That is why the head and duodenum are removed together (Whipple)."}]}},"meta":{"1wlch4f":{"a":"recall","vg":"anat2-pancreas:e0/recall/1"},"6cjtpk":{"a":"recall","vg":"anat2-pancreas:e1/recall/1"},"3yvftx":{"a":"recall","vg":"anat2-pancreas:e8/recall/1"},"1wdeux5":{"a":"recall","vg":"anat2-pancreas:e4/recall/1"},"1f1a749":{"a":"recall","vg":"anat2-pancreas:e5/recall/1"},"1dgp1fw":{"a":"recall","vg":"anat2-pancreas:e6/recall/1"},"w73zs8":{"a":"recall","vg":"anat2-pancreas:e7/recall/1"},"74274b":{"a":"recall","vg":"anat2-pancreas:e7/recall/2"},"1ib9ymw":{"a":"recall","vg":"anat2-pancreas:e8/recall/2"},"fsi8iz":{"a":"recall","vg":"anat2-pancreas:e8/recall/3"},"1c3dj8k":{"a":"recall","vg":"anat2-pancreas:e9/recall/1"},"132wjyj":{"a":"recall","vg":"anat2-pancreas:e10/recall/1"},"10ir5cj":{"a":"recall","vg":"anat2-pancreas:e10/recall/2"}},"explRev":"cb670db19e10"};
